    match = re.match(r"\s*([A-Za-z0-9_.-]+)", str(requirement))
    return match.group(1) if match else ""

def parse_listish(value):
    raw = value.strip()
    if raw.startswith("[") and raw.endswith("]"):
        return re.findall(r'["\']([^"\']+)["\']', raw)
    return [raw.strip('"\'')]

